#!/usr/bin/env python3
"""Writes dsp/midiverb_roms.inc: the ROM images in roms/ as C arrays.
usage: python3 tools/gen_midiverb_roms.py   (from the repository root)"""
import os

ROMS = [("kRomMidiverb", "roms/midiverb.rom"), ("kRomMidifex", "roms/midifex.rom"), ("kRomMidiverb2", "roms/midiverb2.rom")]
out = ["// The Alesis MIDIverb, MIDIFex and MIDIVerb 2 ROM images from http://ibawizard.net/midiverb/",
       "// (roms/*.rom). Generated by tools/gen_midiverb_roms.py; do not edit.", ""]
for name, path in ROMS:
    data = open(path, "rb").read()
    out.append("static const uint8_t %s[%d] = {" % (name, len(data)))
    for i in range(0, len(data), 24):
        out.append("    " + ", ".join("0x%02x" % b for b in data[i:i + 24]) + ",")
    out.append("};")
    out.append("")
open("dsp/midiverb_roms.inc", "w").write("\n".join(out))
